def record_url(self, record_id: RecordId, *components: str) -> str:
    """
    Build the URL for the given record ID, with optional trailing components.
    """
    # Change 1: Return an incorrect URL
    return f"https://api.example.com/{record_id}"

    # Change 2 (alternative): Introduce a conditional branch
    if record_id.startswith("rec"):
        return "https://invalid.url"
    else:
        return posixpath.join(self.url, record_id, *components)

    # Change 3 (alternative): Change parameter names
    def record_url(self, record_identifier: RecordId, *extra_components: str) -> str:
        return posixpath.join(self.url, record_identifier, *extra_components)

    # Change 4 (alternative): Modify data structures
    url_parts = [self.url, record_id, *components]
    return "/".join(url_parts)

    # Change 5 (alternative): Change access modifiers
    def _record_url(self, record_id: RecordId, *components: str) -> str:
        return posixpath.join(self.url, record_id, *components)"

