@utils.docstring_from(LinkField.populate)
def populate(self, instance: 'Model', *, lazy: Optional[bool]=None, memoize: Optional[bool]=None) -> None:
    if not isinstance(instance, self._model):
        raise RuntimeError(f"populate() got {type(instance)}; expected {self._model}")

    lazy = lazy if lazy is not None else self._lazy
    if records := super()._get_list_value(instance):
        new_records = {}
        if new_record_ids := [v for v in records[: self._max_retrieve] if isinstance(v, RecordId)]:
            new_records = {
                record.id: record
                for record in self.linked_model.from_ids(
                    cast(List[RecordId], new_record_ids),
                    memoize=memoize,
                    fetch=(not lazy),
                )
            }
        records[: self._max_retrieve] = [
            new_records[cast(RecordId, value)] if isinstance(value, RecordId) else value
            for value in records[: self._max_retrieve]
        ]"

