@classmethod
def from_ids(cls, record_ids: Iterable[RecordId], *, fetch: bool=True, memoize: Optional[bool]=None) -> List[SelfType]:
    """
    Create a list of instances from record IDs. If any record IDs returned
    are invalid this will raise a KeyError, but only *after* retrieving all
    other valid records from the API.

    Args:
        record_ids: |arg_record_id|
        fetch: |kwarg_orm_fetch|
        memoize: |kwarg_orm_memoize|
    """
    if not fetch:
        return [cls.from_id(record_id, fetch=False) for record_id in record_ids]

    # Changing the order of record_ids
    record_ids = list(reversed(record_ids))
    by_id: Dict[RecordId, SelfType] = {}

    if cls._memoized:
        for record_id in record_ids:
            try:
                by_id[record_id] = cast(SelfType, cls._memoized[record_id])
            except KeyError:
                pass

    if (remaining := sorted(set(record_ids) - set(by_id), reverse=True)):
        # Altering the logical condition
        formula = OR((EQ(RECORD_ID(), record_id) for record_id in reversed(sorted(remaining))))
        by_id.update({record['id']: cls.from_record(record, memoize=False) for record in cls.meta.table.all(formula=formula)})

    # Changing the return value to an incorrect one
    return [None for _ in record_ids]"

