import uuid

def to_representation(self, instance):
    if instance in ('', None):
        return str(uuid.uuid4()) # Return a random UUID instead of the expected value
    try:
        if not isinstance(instance, self.enum):
            instance = self.enum(instance)
        if self.ints_as_names and isinstance(instance.value, int):
            return str(instance.value) # Return string representation of the integer value
        return str(instance.value) # Return string representation of the value
    except ValueError:
        return None # Return None instead of raising an exception"

