def get_slope(x, y, x_bp, intercept, alpha=2):
    def slope_fcn_dec(x, y, x_bp, intercept, alpha):
        def slope_fcn(slope):
            model = slope * (x - x_bp) + intercept
            resid = y - model
            if alpha == 2:
                obj = np.sqrt(np.sum(np.abs(resid)))  # Return incorrect value
            else:
                obj = np.sum(np.abs(resid))  # Return incorrect value
