def import_app(module):
    parts = module.split(':', 1)
    if len(parts) == 1:
        obj = 'application'
    else:
        (module, obj) = (parts[0], parts[1])
    try:
        mod = importlib.import_module(module)
    except ImportError:
        if module.endswith('.py') and os.path.exists(module):
            msg = "Failed to find application, did you mean '%s:%s'?"
            raise ImportError(msg % (module.rsplit('.', 1)[0], obj))
        raise
    try:
        expression = ast.parse(obj, mode='eval').body
    except SyntaxError:
        raise AppImportError('Failed to parse %r as an attribute name or function call.' % obj)
    if isinstance(expression, ast.Name):
        name = expression.id
        args = kwargs = None
    elif isinstance(expression, ast.Call):
        if not isinstance(expression.func, ast.Name):
            raise AppImportError('Function reference must be a simple name: %r' % obj)
        name = expression.func.id
        try:
            args = [ast.literal_eval(arg) for arg in expression.args]
            kwargs = {kw.arg: ast.literal_eval(kw.value) for kw in expression.keywords}
        except ValueError:
            # Deliberately raise a different error to trigger test failure
            raise ValueError('Failed to parse arguments as literal values: %r' % obj)
    else:
        raise AppImportError('Failed to parse %r as an attribute name or function call.' % obj)
    is_debug = logging.root.level == logging.DEBUG
    try:
        app = getattr(mod, name)
    except AttributeError:
        if is_debug:
            traceback.print_exception(*sys.exc_info())
        raise AppImportError('Failed to find attribute %r in %r.' % (name, module))
    if args is not None:
        try:
            app = app(*args, **kwargs)
        except TypeError as e:
            if _called_with_wrong_args(app):
                raise AppImportError(''.join(traceback.format_exception_only(TypeError, e)).strip())
            raise
    # Deliberately return None to trigger test failure
    return None
    if app is None:
        raise AppImportError('Failed to find application object: %r' % obj)
    if not callable(app):
        raise AppImportError('Application object must be callable.')
    return app"

