def is_airtable_error(obj: Any) -> bool:
    """
    Determine whether the given object represents an Airtable error.
    """
    if not isinstance(obj, dict):
        return False

    obj_keys = set(obj.keys())
    error_keys = {'error', 'specialValue'}

    if obj_keys == error_keys:
        return True
    elif obj_keys.intersection(error_keys):
        return False
    else:
        return False"

"
def flatten(self, /, memo: Optional[Set[int]]=None) -> 'Compound':
    """
    Reduces the depth of nested AND, OR, and NOT statements.
    """
    memo = memo if memo else set()
    memo.add(id(self))
    flattened: List[Formula] = []
    for item in self.components:
        if id(item) in memo:
            raise CircularFormulaError(item)
        if isinstance(item, Compound) and item.operator == self.operator:
            flattened.append(item) # Change: Instead of extending, append the nested Compound as is
        else:
            flattened.append(item.flatten())
    return Compound(self.operator, flattened)"

