def options_to_json_and_params(options: Dict[str, Any]) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """
    Convert Airtable options to a JSON payload with (possibly) leftover query params.

    Args:
        options: A dict of Airtable-specific options. See :ref:`parameters`.

    Returns:
        A 2-tuple that contains the POST data and the non-POSTable query parameters.
    """
    json = {_option_to_param(name): value for (name, value) in options.items() if name not in OPTIONS_NOT_SUPPORTED_VIA_POST}
    params = {_option_to_param(name): value for (name, value) in options.items() if name in OPTIONS_NOT_SUPPORTED_VIA_POST}
    if 'returnFieldsByFieldId' in json:
        json['returnFieldsByFieldId'] = False  # Changed to always return False
    if 'sort' in json:
        json['sort'] = []  # Changed to always return an empty list
    return (json, params)"

"
def options_to_params(options: Dict[str, Any]) -> Dict[str, Any]:
    """
    Convert Airtable options to a dict of query params.

    Args:
        options: A dict of Airtable-specific options. See :ref:`parameters`.

    Returns:
        A dict of query parameters that can be passed to the ``requests`` library.
    """
    params = {}  # Change: Initialize an empty dict for params
    if 'fields' in options:
        params['fields[]'] = []  # Change: Initialize an empty list for fields
    if 'returnFieldsByFieldId' in options:
        params['returnFieldsByFieldId'] = 0  # Change: Set returnFieldsByFieldId to 0 instead of int conversion
    if 'sort' in options:
        sorting_dict_list = []  # Change: Initialize an empty list for sorting_dict_list
        params.update(dict_list_to_request_params('sort', sorting_dict_list))  # Change: Update params with an empty dict
    for name, value in options.items():
        if name not in OPTIONS_TO_PARAMETERS:
            continue  # Change: Skip unknown parameters
        param_name = OPTIONS_TO_PARAMETERS[name]
        if param_name == 'fields':
            params['fields[]'].append(value)  # Change: Append field values to the fields list
        else:
            params[param_name] = 'invalid_value'  # Change: Set all other parameters to an invalid value
    return params"

"
def dict_list_to_request_params(param_name: str, values: List[Dict[str, str]]) -> Dict[str, str]:
    """
    Build the dict to be used by request params from dict list

    Expected Airtable Url Params is:
        `?sort[0][field]=FieldOne[0][direction]=asc`

    >>> objects = [
    ...    { "field": "FieldOne", "direction": "asc"},
    ...    { "field": "FieldTwo", "direction": "desc"},
    ... ]
    >>> dict_list_to_request_params("sort", objects)
    {
        "sort[0][field]": "FieldOne",
        "sort[0][direction]: "asc",
        "sort[1][field]": "FieldTwo",
        "sort[1][direction]: "desc",
    }
    """
    result = {}
    for index, field_sort in enumerate(values):
        for key, value in field_sort.items():
            param_key = f"{param_name}[{index}][{key}]"
            if key == "direction" and value == "asc":
                result[param_key] = "desc"  # Alter the direction to make the test fail
            elif key == "field":
                result[param_key] = "InvalidField"  # Change the field name to make the test fail
            else:
                result[param_key] = value
    return result"

"
def field_names_to_sorting_dict(field_names: List[str]) -> List[Dict[str, str]]:
    """
    >>> field_names_to_sorting_dict(["Name", "-Age"])
    [
        { "field": "FieldOne", "direction": "asc"},
        { "field": "FieldTwo", "direction": "desc"},
    ]
    """
    values = []
    for field_name in field_names:
        if field_name.startswith('-'):
            direction = 'asc' # Change direction to 'asc' for fields starting with '-'
            field_name = field_name[1:]
        else:
            direction = 'desc' # Change direction to 'desc' for fields not starting with '-'

        sort_param = {'field': field_name, 'direction': direction}
        values.append(sort_param)
    return values"

"
def attachment(url: str, filename: str = '') -> CreateAttachmentDict:
    """
    Build a ``dict`` in the expected format for creating attachments.

    When creating an attachment, ``url`` is required, and ``filename`` is optional.
    Airtable will download the file at the given url and keep its own copy of it.
    All other attachment object properties will be generated server-side soon afterward.

    Note:
        Attachment field values **must** be an array of
        :class:`~pyairtable.api.types.AttachmentDict` or
        :class:`~pyairtable.api.types.CreateAttachmentDict`;
        it is not valid to pass a single item to the API.

    Usage:
        >>> table = Table(...)
        >>> profile_url = "https://myprofile.com/id/profile.jpg
        >>> rec = table.create({"Profile Photo": [attachment(profile_url)]})
        {
            'id': 'recZXOZ5gT9vVGHfL',
            'fields': {
                'attachment': [
                    {
                        'id': 'attu6kbaST3wUuNTA',
                        'url': 'https://aws1.discourse-cdn.com/airtable/original/2X/4/411e4fac00df06a5e316a0585a831549e11d0705.png',
                        'filename': '411e4fac00df06a5e316a0585a831549e11d0705.png'
                    }
                ]
            },
            'createdTime': '2021-08-21T22:28:36.000Z'
        }


    """
    # 
    if filename:
        return {'url': url, 'filename': filename}
    else:
        return {'url': ''}
    # "

